<script setup lang="ts">import type{Post}from'../types';defineProps<{post:Post}>()</script><template><article class="card"><div class="meta"><span :class="post.category==='随笔'?'purple':''">{{post.category}}</span> · {{post.readingMinutes}} 分钟阅读</div><h2><RouterLink :to="`/posts/${post.slug}`">{{post.title}}</RouterLink></h2><p>{{post.summary}}</p><div class="row"><time>{{post.publishedAt?.slice(0,10)}}</time><span class="tags"><RouterLink v-for="t in post.tags" :key="t" :to="`/posts?tag=${encodeURIComponent(t)}`">#{{t}}</RouterLink></span></div></article></template>
